OUT = ROOT / "docs/house-review/sources"
OUT.mkdir(parents=True, exist_ok=True)
SPECS = [
    ("chair", "06-living-details.png", (1080,1440), [(551,573),(656,570),(711,589),(750,624),(747,824),(767,842),(765,885),(745,903),(741,930),(715,952),(555,952),(511,938),(484,911),(481,878),(476,870),(481,841),(509,823),(508,630),(528,591)]),
    ("couch", "06-living-details.png", (1080,1440), [(226,223),(243,201),(300,187),(405,172),(488,174),(513,189),(519,233),(501,256),(512,290),(495,320),(508,347),(559,343),(608,353),(638,371),(645,407),(609,428),(373,470),(287,464),(240,444),(225,411),(223,374),(239,340),(224,307),(235,272),(224,254)]),
    ("table", "06-living-details.png", (1080,1440), [(769,793),(883,796),(886,843),(913,858),(910,900),(865,919),(865,950),(900,955),(900,960),(778,960),(786,919),(763,895),(760,850)]),
    ("bed", "03-bedroom-bath-library.png", (977,1302), [(148,278),(162,278),(165,337),(181,309),(207,294),(232,307),(239,332),(240,284),(243,266),(258,266),(257,422),(371,416),(397,426),(393,532),(384,544),(383,565),(375,570),(367,568),(366,550),(334,548),(330,573),(317,575),(317,550),(154,548),(150,574),(135,575),(136,531)]),
    ("bathtub", "13-sims-bathroom.png", (920,2048), [(55,585),(94,568),(315,568),(387,592),(407,623),(386,668),(341,700),(375,711),(369,732),(269,729),(255,709),(149,696),(130,712),(92,702),(78,675)]),
    ("sink", "03-bedroom-bath-library.png", (977,1302), [(132,818),(144,807),(157,813),(151,835),(175,837),(176,813),(187,806),(197,814),(194,838),(208,835),(209,815),(219,813),(229,820),(221,840),(217,850),(220,877),(214,905),(176,917),(136,906),(130,874),(126,850),(138,838)]),
    ("toilet", "03-bedroom-bath-library.png", (977,1302), [(276,736),(356,737),(348,761),(346,855),(341,869),(353,881),(349,920),(324,944),(316,958),(325,972),(313,980),(267,978),(261,965),(273,944),(247,938),(227,917),(228,880),(274,878),(275,857)]),
    ("barrel", "12-sims-bedroom.png", (920,2048), [(87,590),(104,574),(184,575),(197,590),(199,673),(181,692),(103,692),(81,671)]),
    ("chest", "03-bedroom-bath-library.png", (977,1302), [(478,525),(480,512),(499,508),(540,522),(555,527),(563,531),(580,538),(590,562),(584,583),(562,597),(491,578),(481,560),(474,548)]),
    ("gary", "02-living-room.png", (1080,1440), [(137,675),(176,654),(221,665),(242,697),(260,680),(280,686),(296,716),(280,746),(304,840),(316,854),(296,868),(241,860),(202,851),(157,826),(125,823),(116,806),(145,787)]),
    ("lounger", "08-storage-roofgarden.png", (1080,1440), [(345,1057),(393,1060),(409,1129),(495,1125),(537,1121),(551,1154),(526,1155),(524,1237),(511,1245),(506,1164),(417,1182),(402,1237),(388,1240),(392,1177)]),
    ("treasure", "08-storage-roofgarden.png", (1080,1440), [(352,160),(427,164),(465,149),(518,136),(557,167),(610,136),(636,159),(666,160),(694,252),(707,347),(688,456),(633,480),(351,480),(325,405),(325,288)]),
]
rows = []
for idx, (name, filename, size, poly) in enumerate(SPECS):
    source = ROOT / "docs/refs/pineapple-house" / filename
    image = Image.open(source).convert("RGBA").resize(size)
    mask = Image.new("L", size)
    ImageDraw.Draw(mask).polygon(poly, fill=255)
    image.putalpha(mask)
    bbox = mask.getbbox()
    piece = image.crop(bbox)
    canvas = Image.new("RGBA", (768,768))
    piece.thumbnail((666,666), Image.Resampling.LANCZOS)
    canvas.alpha_composite(piece, ((768-piece.width)//2,(768-piece.height)//2))
    path = OUT / f"{name}.png"
    canvas.save(path)
    rows.append({"id":name,"source":f"docs/refs/pineapple-house/{filename}","sourceSha256":hashlib.sha256(source.read_bytes()).hexdigest(),"preprocessing":{"size":size,"polygon":poly},"reference":f"docs/house-review/sources/{name}.png","referenceSha256":hashlib.sha256(path.read_bytes()).hexdigest(),"seed":20261009+idx,"status":"prepared"})
(OUT / "references.json").write_text(json.dumps(rows, ensure_ascii=False, indent=2)+"\n", encoding="utf-8")
print(f"prepared {len(rows)} isolated references")
